let AKTIF = "en";

export function T(anahtar, degerler = {}) {
  const m = (S[AKTIF] || {})[anahtar] ?? anahtar;
  return m.replace(/\{(\w+)\}/g, (_, k) => (k in degerler ? degerler[k] : `{${k}}`));
}

function cevir(dugum) {
  const sozluk = S[AKTIF];
  if (!sozluk) return;
  const metinDugumu = (n) => {
    const ham = n.nodeValue, kirp = ham.trim();
    if (!kirp) return;
    let c = sozluk[kirp], on = "";
    if (c === undefined && kirp.startsWith("· ")) { c = sozluk[kirp.slice(2)]; on = "· "; }
    if (c === undefined) return;
    const yeni = ham.replace(kirp, on + c);
    if (yeni !== ham) n.nodeValue = yeni;          // ayni deger yazilirsa gozlemci sonsuz donguye girer
  };
  const ozellik = (el) => {
    for (const a of ["placeholder", "aria-label", "title"]) {
      const v = el.getAttribute && el.getAttribute(a);
      if (v && sozluk[v.trim()] !== undefined && sozluk[v.trim()] !== v) el.setAttribute(a, sozluk[v.trim()]);
    }
  };
  if (dugum.nodeType === 3) return metinDugumu(dugum);
  if (dugum.nodeType !== 1 || dugum.closest?.("textarea, .metin, .pmetin, [data-cevirme]")) return;
  ozellik(dugum);
  const w = document.createTreeWalker(dugum, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT);
  for (let n = w.nextNode(); n; n = w.nextNode()) {
    if (n.nodeType === 1) { if (n.matches("textarea, script, style, [data-cevirme]")) continue; ozellik(n); }
    else if (!n.parentElement?.closest("textarea, script, style, [data-cevirme]")) metinDugumu(n);
  }
}

export function baslat(dil) {
  AKTIF = DILLER[dil] ? dil : "en";
  document.documentElement.lang = AKTIF;
  document.documentElement.dir = AKTIF === "ar" ? "rtl" : "ltr";
  if (AKTIF === "en") return AKTIF;
  cevir(document.body);
  new MutationObserver((kayitlar) => {
    for (const k of kayitlar) {
      if (k.type === "characterData") cevir(k.target);
      k.addedNodes.forEach(cevir);
    }
  }).observe(document.body, { childList: true, subtree: true, characterData: true });
  return AKTIF;
}

export function secili() {
  const url = new URLSearchParams(location.search).get("dil");   // siteden gelen dil her zaman kazanir
  if (url && DILLER[url]) { try { localStorage.setItem("fz_dil", url); } catch {} return url; }
  const kayit = (() => { try { return JSON.parse(localStorage.getItem("fz_kayit") || "null"); } catch { return null; } })();
  const aday = localStorage.getItem("fz_dil") || kayit?.dil || (navigator.language || "en").split("-")[0];
  return DILLER[aday] ? aday : "en";
}
